import pytest
from text import slugify


def test_basic():
    assert slugify("Hello World") == "hello-world"


def test_lowercase():
    assert slugify("UPPER CASE") == "upper-case"


def test_special_characters():
    assert slugify("Hello, World!") == "hello-world"


def test_multiple_spaces():
    assert slugify("too   many   spaces") == "too-many-spaces"


def test_underscores():
    assert slugify("snake_case_string") == "snake-case-string"


def test_hyphens_preserved():
    assert slugify("already-slugged") == "already-slugged"


def test_leading_trailing_hyphens():
    assert slugify("  -leading and trailing-  ") == "leading-and-trailing"


def test_numbers():
    assert slugify("article 42 published") == "article-42-published"


def test_empty_string():
    assert slugify("") == ""


def test_only_special_chars():
    assert slugify("!!! ???") == ""


def test_mixed_symbols():
    assert slugify("C++ is great!") == "c-is-great"

import unittest
from text import slugify


class TestSlugify(unittest.TestCase):

    def test_basic(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_lowercase(self):
        self.assertEqual(slugify("UPPER CASE"), "upper-case")

    def test_special_characters(self):
        self.assertEqual(slugify("Hello, World!"), "hello-world")

    def test_multiple_spaces(self):
        self.assertEqual(slugify("too   many   spaces"), "too-many-spaces")

    def test_underscores(self):
        self.assertEqual(slugify("snake_case_string"), "snake-case-string")

    def test_hyphens_preserved(self):
        self.assertEqual(slugify("already-slugged"), "already-slugged")

    def test_leading_trailing_hyphens(self):
        self.assertEqual(slugify("  -leading and trailing-  "), "leading-and-trailing")

    def test_numbers(self):
        self.assertEqual(slugify("article 42 published"), "article-42-published")

    def test_empty_string(self):
        self.assertEqual(slugify(""), "")

    def test_only_special_chars(self):
        self.assertEqual(slugify("!!! ???"), "")

    def test_mixed_symbols(self):
        self.assertEqual(slugify("C++ is great!"), "c-is-great")


if __name__ == "__main__":
    unittest.main()
